<?php requireLogin(); $s=$pdo->prepare('SELECT a.*,sa.unlocked_at FROM achievements a LEFT JOIN student_achievements sa ON sa.achievement_id=a.id AND sa.student_id=? ORDER BY a.xp_requirement');$s->execute([userId()]);$rows=$s->fetchAll(); ?>
<section class="hero"><h1>🏅 Achievements</h1><p>Collect badges by learning and completing challenges.</p></section><br><div class="grid"><?php foreach($rows as $a): ?><div class="card"><span class="badge"><?= $a['unlocked_at']?'UNLOCKED':'LOCKED' ?></span><h2><?=h(lang()==='ar'?$a['name_ar']:$a['name_en'])?></h2><p><?=h(lang()==='ar'?$a['description_ar']:$a['description_en'])?></p><p>XP requirement: <?=$a['xp_requirement']?></p></div><?php endforeach; ?></div>
